/// <summary>
/// PaffH 11.12.24
/// fill order quantity
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXManualPALabelWizard, NDXProdIdentControlPanelTmp_AnzahlEtiketten), FormControlEventType::Modified)]
public static void NDXProdIdentControlPanelTmp_AnzahlEtiketten_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormIntControl anzalEtiketten = sender as FormIntControl;
    FormRun formRun = sender.formRun();
    if (formRun is NDXManualPALabelWizardI)
    {
        NDXManualPALabelWizardI nDXManualPALabelWizard = formRun as NDXManualPALabelWizardI;
        NDXManualPALabelWizard sysWizard = nDXManualPALabelWizard.parmSysWizard();
        sysWizard.parmOrderQty(anzalEtiketten.value());
    }
}

