/// <summary>
/// PaffH 06.05.24
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXManualPALabelWizard, FormButtonGetData), FormControlEventType::Clicked)]
public static void FormButtonGetData_OnClicked(FormControl sender, FormControlEventArgs e)
{
    List listContract = new List(Types::Class);
    FormRun formRun = sender.formRun();
    if (formRun is NDXManualPALabelWizardI)
    {
        Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract contract;
        NDXManualPALabelWizardI nDXManualPALabelWizard = formRun as NDXManualPALabelWizardI;
        nDXManualPALabelWizard.fillNDXProdIdentControlPanel();
        NDXManualPALabelWizard sysWizard = nDXManualPALabelWizard.parmSysWizard();
        listContract = sysWizard.getData();
        ListEnumerator enum = listContract.getEnumerator();
        sysWizard.initializeNDXProdIdentControlPanelList();
        while (enum.moveNext())
        {
            contract = enum.current();
            if (contract && contract.BT_RecordId != 0)
            {
                nDXManualPALabelWizard.updateNDXProdIdentControlPanelFromContract(contract);
            }
            else
            {
                error("@NDX:NDXLabelDataCouldNotBeDetermined");
            }
        }
        nDXManualPALabelWizard.setQRCodeImage();
    }
}

